    INSERT INTO mcqs (topic_id, question, options, correct_index, explanation) VALUES
    (v_topic_id, 'Which of the following is true regarding "Decision-Making Capacity"?', '["It is a legal determination made by a judge", "It is a clinical determination made by a physician for a specific decision at a specific time", "It is the same as ''competence", "Once a patient lacks capacity, it is permanent"]', 1, 'Capacity is a clinical assessment by a doctor for a specific decision. "Competence" is a legal term determined by a court. Capacity can fluctuate (e.g., due to delirium or medication).'),
    (v_topic_id, 'To have decision-making capacity, a patient must be able to do all of the following EXCEPT:', '["Communicate a choice", "Understand the relevant clinical information", "Agree with the physician''s recommendation", "Appreciate the consequences of the decision"]', 2, 'A patient with capacity has the right to disagree with the physician. The four elements are: Communication of choice, Understanding, Appreciation of consequences, and Rationalization/Reasoning.'),
    (v_topic_id, 'A 75-year-old woman with mild dementia is being asked to consent to a skin biopsy. She understands the procedure and why it is being done. Does she have capacity?', '["No, patients with dementia automatically lack capacity", "Yes, capacity is decision-specific; a patient can have capacity for a simple decision even if they lack it for a complex one", "Only if her family agrees", "Only if a psychiatrist confirms it"]', 1, 'Capacity is not "all or nothing." A patient might have the capacity to consent to a simple biopsy but not to a complex heart surgery.'),
    (v_topic_id, 'Which of the following documents is used to appoint a specific person to make medical decisions if the patient becomes incapacitated?', '["Living Will", "Durable Power of Attorney for Healthcare (Healthcare Proxy)", "Last Will and Testament", "DNAR Order"]', 1, 'The Durable Power of Attorney for Healthcare (or Healthcare Proxy) designates a surrogate decision-maker.'),
    (v_topic_id, 'A "Living Will" primarily outlines:', '["Who should inherit the patient''s money", "The patient''s preferences for specific treatments (like intubation or feeding tubes) in end-of-life scenarios", "Who should be the guardian of the patient''s children", "The patient''s funeral arrangements"]', 1, 'A Living Will provides specific instructions about medical treatments the patient wants or does not want if they cannot speak for themselves.'),
    (v_topic_id, 'A patient has both a Living Will and a designated Healthcare Proxy. The proxy wants a treatment that the Living Will explicitly refuses. Which typically takes precedence?', '["The Healthcare Proxy''s current decision", "The instructions in the Living Will", "The physician''s preference", "The family''s consensus"]', 1, 'A Living Will is a direct expression of the patient''s autonomy. A proxy is supposed to follow those instructions. If the instructions are clear and applicable, they generally take precedence.'),
    (v_topic_id, 'Which of the following is the preferred standard for a surrogate making a decision for a previously competent patient?', '["Best Interests Standard", "Substituted Judgment", "Physician-Directed Standard", "Court-Ordered Standard"]', 1, 'Substituted judgment aims to choose what the patient *would have* chosen for themselves based on their known values and beliefs.'),
    (v_topic_id, 'When is the "Best Interests Standard" used by a surrogate?', '["When the patient''s prior wishes and values are unknown", "When the patient is a child who was never competent", "Both A and B", "Never"]', 2, 'The Best Interests Standard is used when there is no evidence of what the patient would have wanted, so the surrogate must choose the most objectively beneficial path.'),
    (v_topic_id, 'A 20-year-old man is in a persistent vegetative state after a car accident. He never discussed his end-of-life wishes. His parents want to remove life support, while his wife wants to continue it. Who is the legal surrogate?', '["The parents", "The wife", "The hospital", "The court must decide"]', 1, 'In the legal hierarchy of surrogates, a spouse typically comes before parents.'),
    (v_topic_id, 'A "DNR" (Do Not Resuscitate) order specifically applies to:', '["All medical treatments, including antibiotics", "Cardiopulmonary Resuscitation (CPR) in the event of cardiac or respiratory arrest", "Transfer to the ICU", "Intubation for respiratory failure"]', 1, 'A DNR only means "do not perform CPR if the heart stops." It does not mean "do not treat" other conditions.'),
    (v_topic_id, 'A "POLST" or "MOLST" form differs from a Living Will in that it is:', '["Only for wealthy patients", "A set of actionable medical orders signed by a physician, meant to be followed by EMS and other providers in various settings", "Not legally binding", "Only for patients in nursing homes"]', 1, 'POLST (Physician Orders for Life-Sustaining Treatment) turns the patient''s wishes into actual medical orders that are recognized across the healthcare system.'),
    (v_topic_id, 'A patient with capacity says "I want to be a DNR," but their family objects. The physician should:', '["Follow the family''s wishes to avoid a lawsuit", "Honor the patient''s request and write the DNR order", "Wait for the patient to lose capacity", "Consult a lawyer"]', 1, 'A competent patient''s request for a DNR order must be honored, regardless of family disagreement.'),
    (v_topic_id, 'Which of the following is a potential sign that a patient lacks decision-making capacity?', '["Refusing a recommended treatment", "Inability to explain the reasoning behind their choice", "Having a diagnosis of schizophrenia", "Being over the age of 80"]', 1, 'Refusal or a psychiatric diagnosis does not automatically mean lack of capacity. The inability to reason through the decision is a core indicator of incapacity.'),
    (v_topic_id, 'Does a psychiatric consultation *required* to determine decision-making capacity?', '["Yes, only psychiatrists can determine capacity", "No, any physician can determine capacity for the decisions related to their own specialty", "Only if the patient is on a ''72-hour hold", "Only if the patient is non-verbal"]', 1, 'Any doctor can assess capacity. Psychiatrists are often called in for complex cases or when a psychiatric illness is the primary cause of the impairment.'),
    (v_topic_id, 'A surrogate decision-maker refuses a life-saving blood transfusion for a child based on religious beliefs. The physician should:', '["Respect the parents'' religious freedom", "Seek an emergency court order to treat the child", "Call the police", "Do nothing"]', 1, 'While adults can refuse life-saving care for themselves, they generally cannot refuse it for their minor children. The state has a "parens patriae" duty to protect the child.'),
    (v_topic_id, 'Which of the following is true about "Slow Codes" or "Show Codes" (performing CPR half-heartedly to appease a family)?', '["They are a good way to manage difficult families", "They are ethically deceptive and medically inappropriate", "They are required if the family refuses a DNR", "They protect the doctor from liability"]', 1, 'Slow codes are widely considered unethical as they involve deception and provide no medical benefit.'),
    (v_topic_id, 'A patient is in the early stages of Alzheimer''s and wants to plan for the future. What is the most important step?', '["Write a Will for their money", "Appoint a Healthcare Proxy and discuss their values and preferences while they still have capacity", "Move to a nursing home immediately", "Stop all medications"]', 1, 'Early planning while capacity is preserved is essential for ensuring the patient''s autonomy is respected later.'),
    (v_topic_id, 'Can a Healthcare Proxy make a decision that contradicts the patient''s known values?', '["Yes, if the proxy thinks it''s better", "No, the proxy is legally and ethically bound to follow the ''Substituted Judgment'' standard", "Only if the doctor agrees", "Only if the whole family agrees"]', 1, 'The proxy''s role is to act as the patient''s voice, not their own.'),
    (v_topic_id, 'A 19-year-old college student is in a coma after a binge-drinking incident. He has no proxy. His girlfriend says he wouldn''t want to be on a ventilator. His parents disagree. Whose word carries more weight?', '["The girlfriend", "The parents", "The college dean", "The doctor"]', 1, 'In the absence of a legal proxy, the legal hierarchy (Parents > Girlfriend/Friends) prevails, even if the friend claims to know the patient better.'),
    (v_topic_id, 'The "Cruzan" case in the US Supreme Court established that:', '["Physician-assisted suicide is a right", "States can require ''clear and convincing evidence'' of an incapacitated patient''s wishes before withdrawing life support", "Parents can always refuse treatment for children", "Living wills are mandatory"]', 1, 'The Cruzan case emphasized the importance of clear evidence of a patient''s prior wishes in end-of-life decisions.'),
    (v_topic_id, 'A patient with end-stage renal disease decides to stop dialysis. They understand they will die within days. This is an act of:', '["Suicide", "Refusal of life-sustaining treatment", "Euthanasia", "Medical neglect"]', 1, 'Choosing to stop a medical intervention (even a life-sustaining one) is a legal and ethical right of a competent patient, distinct from suicide.'),
    (v_topic_id, 'Which of the following describes "Passive Euthanasia"?', '["Giving a lethal injection", "Withholding or withdrawing life-sustaining treatment (e.g., stopping a ventilator)", "Prescribing a lethal dose of medication", "None of the above"]', 1, 'The term "passive euthanasia" is falling out of favor; it is now simply referred to as "withdrawing or withholding life-sustaining treatment."'),
    (v_topic_id, '"Active Euthanasia" (a physician directly administering a lethal drug) is:', '["Legal in all US states", "Illegal in all US states", "Legal only in Oregon", "Legal only for terminal cancer"]', 1, 'Direct active euthanasia is illegal in the United States. (Physician-assisted dying, where the patient self-administers the drug, is legal in some states).'),
    (v_topic_id, 'A patient has a "DNI" (Do Not Intubate) order but does *not* have a "DNR" order. Their heart stops. Should the physician perform chest compressions and give Epinephrine?', '["No, DNI implies DNR", "Yes, but they cannot intubate if the heart starts and the patient remains in respiratory failure", "No, they should do nothing", "Only if the family asks"]', 1, 'DNI and DNR are separate orders. If the patient has a pulse and goes into respiratory arrest, they cannot be intubated. If the heart stops, CPR can be performed (but without intubation).'),
    (v_topic_id, 'The principle of "Prospective Autonomy" refers to:', '["The right of a child to grow up", "The right of a patient to make decisions now that will be honored in the future if they lose capacity", "The right to sue for future damages", "None of the above"]', 1, 'Advance directives are the primary way to exercise prospective autonomy.'),
    (v_topic_id, 'A patient with severe depression refuses a life-saving surgery for a ruptured appendix. The physician suspects the refusal is motivated by a desire to die due to the depression. The physician should:', '["Respect the refusal", "Perform an emergency capacity assessment; if the depression is impairing the patient''s ability to reason, they may lack capacity for this specific decision", "Wait for the patient to die", "Call the patient''s therapist"]', 1, 'Severe mental illness can impair the "reasoning" element of capacity, especially if the refusal is a symptom of the illness.'),
    (v_topic_id, 'Is a "Court-Appointed Guardian" the same as a "Healthcare Proxy"?', '["Yes", "No, a guardian is appointed by a court when there is no proxy and the patient is deemed incompetent", "Only in some states", "Only if they are a family member"]', 1, 'A proxy is chosen by the patient; a guardian is chosen by a judge.'),
    (v_topic_id, 'A surrogate refuses to allow a patient to be enrolled in a "Minimal Risk" research study. The physician should:', '["Enroll them anyway", "Respect the surrogate''s refusal", "Overrule the surrogate", "Ask the IRB"]', 1, 'Surrogates have the authority to refuse research participation for incapacitated patients.'),
    (v_topic_id, 'Which of the following is a common "Contextual Feature" that might complicate an ethics case?', '["The patient''s blood type", "A conflict of interest where the doctor is also a researcher in the study the patient is enrolled in", "The color of the hospital walls", "The patient''s favorite food"]', 1, 'Conflicts of interest are critical contextual features in ethics cases.'),
    (v_topic_id, 'A patient is brain dead. The family refuses to remove the ventilator. Ethically and legally, the physician:', '["Must keep the ventilator on forever", "Can withdraw the ventilator, as brain death is the legal definition of death", "Must wait for the heart to stop", "Must get a court order"]', 1, 'Once brain death is declared following standard protocols, the person is legally dead. Continued ventilation is not "life support" but "organ support." (Some states allow a short period for family to gather).'),
    (v_topic_id, '"Brain Death" requires:', '["A flat EEG", "Irreversible loss of all functions of the entire brain, including the brainstem", "A persistent vegetative state", "A coma"]', 1, 'Brain death is the irreversible cessation of all clinical brain function.'),
    (v_topic_id, 'Can a pregnant woman refuse a C-section that is necessary for the life of the fetus?', '["No, the fetus has a right to life", "Yes, a competent pregnant woman has the same right to refuse medical interventions as anyone else", "Only if she is married", "Only if her life is not in danger"]', 1, 'In the US, maternal autonomy generally prevails, and courts have almost always refused to force obstetric procedures.'),
    (v_topic_id, 'A 15-year-old girl is pregnant. She wants to have an abortion. Her parents refuse. What is the standard in many states?', '["She must have the parents'' consent", "She can seek a ''Judicial Bypass'' to get permission from a judge instead of her parents", "She cannot have an abortion", "The physician decides"]', 1, 'Judicial bypass is a constitutional requirement in states that mandate parental involvement for a minor''s abortion.'),
    (v_topic_id, 'A patient in a coma has no advance directives and no family. The "Surrogate of Last Resort" in some jurisdictions is:', '["The hospital CEO", "A public guardian or a physician-led committee", "The patient''s lawyer", "The police"]', 1, 'States have different mechanisms for "unrepresented" patients, often involving an ethics committee or a public guardian.'),
    (v_topic_id, 'Which of the following is true regarding "Comfort Care Only" orders?', '["The patient must be in the ICU", "The focus shifts from curative treatment to aggressive symptom management (pain, dyspnea, anxiety)", "The patient is not given any food or water", "The patient must be sedated"]', 1, 'Comfort care focuses on quality of life and relief of suffering.'),
    (v_topic_id, 'A surrogate wants to withdraw a feeding tube from a patient in a permanent vegetative state. This is:', '["Illegal", "Legal and ethically permissible as withdrawing any other life-sustaining treatment", "Only legal if the patient is a DNR", "Murder"]', 1, 'Artificial nutrition and hydration are considered medical treatments that can be withdrawn or withheld.'),
    (v_topic_id, 'Does a DNR order expire?', '["Yes, every 30 days", "No, but it should be reviewed during setiap hospital admission or change in clinical status", "Only if the patient leaves the state", "Only if the doctor changes"]', 1, 'DNR orders don''t have a "hard" expiration but must be re-verified if the patient moves between care settings (e.g., home to hospital).'),
    (v_topic_id, 'A patient with a DNR order is choking on food. Should the physician perform the Heimlich maneuver?', '["No, it''s a DNR", "Yes, the Heimlich maneuver is not CPR and the patient is not in cardiac arrest", "Only if the family says so", "Only if it''s a child"]', 1, 'DNR only applies to cardiac/respiratory arrest. Acute airway obstruction should be managed.'),
    (v_topic_id, 'A "Medical Power of Attorney" is effective:', '["As soon as it is signed", "Only when the patient is determined to lack decision-making capacity", "Only after the patient dies", "Only in the hospital"]', 1, 'The proxy''s authority only "kicks in" when the patient can no longer speak for themselves.'),
    (v_topic_id, 'Can a physician "Fire" a patient for refusing to follow a treatment plan?', '["Yes, but only after providing notice and a period of time for the patient to find a new doctor to avoid abandonment", "No, once you start, you must finish", "Only if the patient is a DNR", "Only if the patient hasn''t paid"]', 0, 'Physicians can terminate the relationship for many reasons, but they must follow a process to ensure continuity of care.'),
    (v_topic_id, 'A patient''s Healthcare Proxy is also the sole beneficiary of the patient''s large life insurance policy. This is a potential:', '["Conflict of interest", "Reason to ignore the proxy", "Sign of a good relationship", "None of the above"]', 0, 'The physician should be aware of potential ulterior motives, though the proxy still has legal standing unless proven to be acting in bad faith.'),
    (v_topic_id, 'A patient is delirious due to a UTI. Can they provide informed consent for a non-urgent surgery?', '["Yes, if they are awake", "No, they lack the ''understanding'' and ''reasoning'' elements of capacity during the period of delirium", "Only if the family agrees", "Only if the surgery is fast"]', 1, 'Delirium is a transient cause of incapacity. Non-urgent decisions should wait until the delirium clears.'),
    (v_topic_id, 'Which of the following is true about "Oral" advance directives?', '["They are never legally valid", "They are legally valid in many states if they were made clearly and repeatedly to others, though a written document is preferred", "They are only valid for 24 hours", "They must be recorded on video"]', 1, 'Witnessed oral statements about future care can be used as "clear and convincing evidence" of a patient''s wishes.'),
    (v_topic_id, 'A patient with a terminal illness is in severe pain. Increasing the morphine dose might hasten their death. Ethically, the physician:', '["Should not increase the dose", "Can increase the dose to relieve the pain, even if death is a foreseeable side effect (Rule of Double Effect)", "Must wait for a court order", "Should switch to Tylenol"]', 1, 'Relieving suffering is a core duty of the physician and is ethically prioritized at the end of life.'),
    (v_topic_id, 'A "Guardian ad Litem" is:', '["A lawyer for the doctor", "A person appointed by a court specifically to represent the best interests of a minor or incapacitated person during a legal proceeding", "A type of insurance", "A medical student"]', 1, 'Guardian ad litem is often used in cases involving children or disputed custody/care.'),
    (v_topic_id, 'Can a patient with a DNR order have surgery?', '["No, it''s too risky", "Yes, but the DNR order is often ''suspended'' or modified during the peri-operative period because anesthesia inherently suppresses vital functions", "Only if they change to ''Full Code", "Only if the surgeon agrees"]', 1, 'It is standard practice to discuss "re-verifying" or temporarily suspending the DNR for the duration of the surgery and recovery.'),
    (v_topic_id, 'A surrogate wants to start a treatment that the physician believes is "Futility" (offers no physiological benefit). The physician should:', '["Start it anyway", "Engage in a conflict-resolution process, involving the ethics committee if necessary, to explain why the treatment is not indicated", "Sue the surrogate", "Ignore the request"]', 1, 'Medical futility is a complex area, but physicians are not obligated to provide non-beneficial care.'),
    (v_topic_id, 'Is it legal to withdraw a ventilator from a patient who is *not* brain dead but has a poor prognosis and whose family wants to stop?', '["No, that''s murder", "Yes, it is the withdrawal of a life-sustaining treatment, which is ethically and legally permissible if it aligns with the patient''s wishes", "Only if the heart stops first", "Only if the patient is a DNR"]', 1, 'Withdrawing treatment is a recognized right, even if it leads to death.'),
    (v_topic_id, 'The "Quinlan" case in the 1970s was significant because it:', '["Legalized abortion", "Recognized the right of a family to withdraw a ventilator from a patient in a persistent vegetative state", "Established the 3-3-2 rule", "Created HIPAA"]', 1, 'Karen Ann Quinlan''s case was a landmark for the "right to die" movement and the role of surrogates.'),
    (v_topic_id, 'If a patient has capacity, who is the primary decision-maker?', '["The spouse", "The doctor", "The patient", "The Healthcare Proxy"]', 2, 'The patient''s own current choice always overrides any previous document or surrogate if the patient has capacity.');
